'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT c.conrelid::regclass::text relation,c.conname name,
      pg_get_constraintdef(c.oid) definition FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace
      WHERE n.nspname='public' ORDER BY 1,2) q WHERE name='shop_products_shop_product_key'),
'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT c.relname relation,t.tgname name,t.tgenabled enabled,
      pg_get_triggerdef(t.oid) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
      JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal ORDER BY 1,2) q WHERE name='catalog_listing_identity_guard'),
'grants',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT table_name,column_name,grantee,privilege_type,is_grantable
      FROM information_schema.column_privileges WHERE table_schema='public'
      AND grantee IN ('PUBLIC','anon','authenticated','service_role') ORDER BY 1,2,3,4) q WHERE table_name IN ('product_submissions','product_submission_decisions','listing_images','catalog_media_config')),
'buckets',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT id,public,file_size_limit,allowed_mime_types
      FROM storage.buckets WHERE id='listing-media' ORDER BY id) q ),
'config',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT * FROM public.catalog_media_config ORDER BY singleton) q ),
'ledger',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') FROM (SELECT version,name FROM supabase_migrations.schema_migrations ORDER BY version) q )),'schema_md5',md5(s::text),'preserved_baseline_md5',md5(jsonb_build_object('grants',(SELECT coalesce(jsonb_agg(item ORDER BY ord),'[]') FROM jsonb_array_elements(s->'grants') WITH ORDINALITY t(item,ord) WHERE concat_ws('|',item->>'table_name') IN ('addresses','banners','brands','cart_items_v2','carts','categories','chat_messages','customer_saved_locations','legal_consents','notifications','order_items','orders','products','profiles','qr_session_items','qr_sessions','reviews','shop_products','shop_ratings','shops','taxonomy_alias_targets','taxonomy_aliases','taxonomy_contract_config','taxonomy_id_allocations','taxonomy_import_runs','taxonomy_node_relationships','verified_transaction_items','verified_transactions','wishlist')),'ledger',(SELECT coalesce(jsonb_agg(item ORDER BY ord),'[]') FROM jsonb_array_elements(s->'ledger') WITH ORDINALITY t(item,ord) WHERE concat_ws('|',item->>'version') IN ('20260812010907','20260812011047','20260812011128','20260812013109','20260812013220','20260812013308','20260812013403','20260814000820','20260815000900','20260829001000','20260830001100')),'tables',(SELECT coalesce(jsonb_agg(item ORDER BY ord),'[]') FROM jsonb_array_elements(s->'tables') WITH ORDINALITY t(item,ord) WHERE concat_ws('|',item->>'name') IN ('public.addresses','public.banners','public.brands','public.cart_items_v2','public.carts','public.categories','public.chat_messages','public.customer_saved_locations','public.legal_consents','public.notifications','public.order_items','public.orders','public.products','public.profiles','public.qr_session_items','public.qr_sessions','public.reviews','public.shop_products','public.shop_ratings','public.shops','public.taxonomy_alias_targets','public.taxonomy_aliases','public.taxonomy_contract_config','public.taxonomy_id_allocations','public.taxonomy_import_runs','public.taxonomy_node_relat